                  <textarea id="widgetAIExpectedOutput" class="form-control widget-ai-textarea" data-agent-binding-field="expected_output" onchange="updateWidgetAgentBindingValue(event)" placeholder="e.g. JSON with status, message, and suggested next_action."></textarea>
